export function buildToolboxPage(){return "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>PanelStock · Fabrication Toolbox</title>\n<style>\n:root{font-family:system-ui,sans-serif;color:#182c35;background:#f3f5f5;font-size:15px}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0}button,input,textarea,select{font:inherit}button{cursor:pointer;border:1px solid #ccd6d8;border-radius:7px;background:white;padding:10px 15px;color:#182c35}button:hover{background:#edf2f1}button.primary{background:#173e45;color:white;border-color:#173e45}button:focus-visible,a:focus-visible{outline:3px solid #e1ae41;outline-offset:3px}header{background:#173039;color:white;padding:24px 5%;display:flex;justify-content:space-between;align-items:center;gap:16px}header small{letter-spacing:2px;color:#edc46a}h1{font-size:25px;margin:5px 0}h2{font-size:24px;margin:0 0 8px}h3{font-size:17px;margin:0 0 12px}p{line-height:1.6}.shell{max-width:1250px;margin:auto;display:grid;grid-template-columns:220px 1fr;gap:28px;padding:32px 24px}nav button{display:block;width:100%;text-align:left;margin-bottom:10px}nav button.active{background:#e0ebe8;border-color:#b2cbc2;font-weight:650}.muted{color:#61737b;font-size:13px}.card{background:white;padding:24px;border:1px solid #dce4e5;border-radius:12px;margin:18px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}label{display:block;font-size:13px;font-weight:600;margin-bottom:6px}input:not([type=checkbox]),textarea,select{width:100%;padding:10px 12px;border:1px solid #c8d3d7;border-radius:6px;background:white;color:#182c35}textarea{min-height:90px;resize:vertical;line-height:1.5}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.between{justify-content:space-between}.tag{background:#f8efd8;color:#6a501c;padding:5px 9px;border-radius:5px;font-size:12px;font-weight:650}.topic{border-top:1px solid #e1e8e8;padding:22px 0}.topic:first-of-type{border:0}.topic .grid{margin:12px 0}.check{display:flex;align-items:center;gap:8px;font-weight:500}input[type=checkbox]{width:18px;height:18px;accent-color:#173e45}.notice{padding:12px 16px;background:#e7efec;border-radius:7px;font-size:13px;line-height:1.5}.actions{position:sticky;bottom:0;background:#f3f5f5ed;padding:16px 0;display:flex;gap:10px;flex-wrap:wrap}.person,.action{border-bottom:1px solid #e1e8e8;padding:12px 0}.action .grid{margin:10px 0}.empty{padding:28px;text-align:center;color:#61737b}#message{position:fixed;right:24px;bottom:24px;background:#173e45;color:white;max-width:450px;padding:16px;border-radius:9px;display:none;z-index:10}#printout{display:none}.report{font:14px Arial,sans-serif;line-height:1.5;color:#172a32}.report h1{font-size:25px}.report h2{font-size:18px;margin-top:25px}.report table{width:100%;border-collapse:collapse}.report td,.report th{border:1px solid #bbc8cd;padding:8px;text-align:left}.report p{white-space:pre-wrap;overflow-wrap:anywhere}.report section{break-inside:avoid}.report small{color:#52656b}@media(max-width:780px){header{align-items:flex-start;flex-direction:column}.shell{display:block;padding:20px 16px}nav{display:flex;gap:8px;flex-wrap:wrap}nav button{width:auto}.grid{grid-template-columns:1fr}.card{padding:18px}}@media print{body>*{display:none!important}#printout{display:block!important}body{background:white}@page{size:A4;margin:16mm}}\ndialog{border:0;border-radius:12px;padding:24px;width:min(620px,95vw);box-shadow:0 12px 60px #0004}dialog::backdrop{background:#142c38aa}#signature-pad{width:100%;height:200px;touch-action:none;border:1px solid #a6b9c1;border-radius:8px;background:white} .signature-image{width:200px;height:65px;object-fit:contain;border-bottom:1px solid #b8c6cb} </style>\n<header><div><small>WORKSHOP SAFETY</small><h1>PanelStock Toolbox</h1></div><div class=\"row\"><span id=\"signed-in\" class=\"muted\" style=\"color:#d8e5e8\"></span><button id=\"logout\" onclick=\"logout()\" hidden>Log out</button></div></header>\n<div class=\"shell\"><nav><button id=\"nav-talk\" onclick=\"view('talk')\">Current talk</button><button id=\"nav-records\" onclick=\"refreshRecords()\">Saved records</button><button id=\"nav-admin\" onclick=\"view('admin')\">Admin templates</button><p class=\"muted\">Signed records are saved to PanelStock. Draft edits stay on this device until you choose Save draft.</p><button onclick=\"backup()\">Export shared records</button><button onclick=\"downloadDraft()\">Back up current draft</button><label for=\"restore\">Recover local draft</label><input id=\"restore\" type=\"file\" accept=\"application/json,.json\" onchange=\"restoreFile(this)\"></nav><main id=\"main\"></main></div><div id=\"message\" role=\"status\" aria-live=\"polite\"></div><div id=\"printout\"></div><dialog id=\"sign-dialog\"><h2 id=\"sign-title\"></h2><p id=\"sign-statement\"></p><p class=\"muted\">Sign below using a finger, stylus or mouse.</p><canvas id=\"signature-pad\" aria-label=\"Draw your signature\"></canvas><div class=\"row\" style=\"margin-top:16px\"><button onclick=\"clearPad()\">Clear</button><button onclick=\"document.getElementById('sign-dialog').close()\">Cancel</button><button class=\"primary\" onclick=\"saveSignature()\">Confirm & save signature</button></div></dialog>\n<script>\n'use strict';\nconst titles=['Hazard identification','Personal protective equipment','Safe work practices','Emergency procedures','Incident reporting & first aid','Questions & discussion'];\nconst daily=['Identify welding fumes, sparks, hot metal, sharp edges, grinding debris, pinch points, suspended loads and forklift traffic. Record today’s hazards and the controls agreed before the task starts.','Check task-specific eye and face protection, hearing protection, footwear, protective clothing and suitable gloves. Confirm respiratory protection requirements, fit and condition against the assessed task.','Confirm hot-work controls, fume extraction, machine guards, isolation procedures, lifting equipment checks and pedestrian separation. Use the approved work method and permits where required.','Confirm the assembly point, evacuation route, emergency contacts and clear access to emergency equipment. Identify any changes for today.','Name the first aider and identify first-aid kit locations. Explain how to report an injury, incident, hazard or near miss promptly under the workplace procedure.','Invite concerns about today’s tasks, unfamiliar work, equipment or controls. Record questions, answers and actions.'];\nconst weekly=['Review recurring fabrication hazards and recent inspections. Select a focus such as welding fumes, hot work, sharp sheet metal, grinding, lifting or vehicle movement.','Discuss PPE selection, limitations, fit, inspection, care and replacement for the selected fabrication tasks. Invite workers to raise equipment concerns.','Review an approved procedure using a practical scenario: hot work, guarding and isolation, lifting, handling material or working around mobile plant. Record improvements.','Review emergency roles and arrangements for fire, serious injury or evacuation. Confirm everyone knows the assembly point and how to raise the alarm.','Discuss relevant incidents and near misses without unnecessary personal details. Review reporting, first-aid arrangements, corrective actions and outstanding follow-up.','Ask what could make work safer, check understanding of the focus topic and revisit unresolved concerns from earlier talks.'];\nlet key='panelstock-toolbox-v1';let state={templates:{daily:[...daily],weekly:[...weekly]},records:[],draft:null},page='talk',storageOK=true;\nconst esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Australia/Brisbane',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());\nfunction fresh(type='daily'){return{id:crypto.randomUUID(),type,date:today(),time:'06:30',company:'',site:'',facilitator:'',tasks:'',focus:'',topics:state.templates[type].map(text=>({text,notes:'',reviewed:false})),people:[],actions:[],status:'Draft',completedAt:null,supervisorSignature:null}}\nfunction validSignature(s){return !s||(typeof s.image==='string'&&s.image.length<500000&&/^data:image\\/png;base64,[A-Za-z0-9+/=]+$/.test(s.image)&&typeof s.at==='string'&&!isNaN(Date.parse(s.at)))}\nfunction validRecord(r){return r&&typeof r.id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(r.id)&&['daily','weekly'].includes(r.type)&&['Draft','Completed'].includes(r.status)&&['date','time','company','site','facilitator','tasks','focus'].every(k=>typeof r[k]==='string')&&Array.isArray(r.topics)&&r.topics.length===6&&r.topics.every(t=>typeof t.text==='string'&&typeof t.notes==='string'&&typeof t.reviewed==='boolean')&&Array.isArray(r.people)&&r.people.every(p=>typeof p.name==='string'&&typeof p.ack==='boolean'&&validSignature(p.signature))&&validSignature(r.supervisorSignature)&&Array.isArray(r.actions)&&r.actions.every(a=>['text','owner','due'].every(k=>typeof a[k]==='string')&&typeof a.closed==='boolean')}\nfunction validState(s){return s&&s.templates&&['daily','weekly'].every(k=>Array.isArray(s.templates[k])&&s.templates[k].length===6&&s.templates[k].every(t=>typeof t==='string'))&&Array.isArray(s.records)&&s.records.every(validRecord)&&(!s.draft||validRecord(s.draft))}\nlet actor=null,token=sessionStorage.getItem('panelstock-toolbox-session')||'',templateRevision=0,recordPage=0,totalRecords=0,openActions=[],openActionTotal=0,nextRecordPage=null,nextActionPage=null,searchTerm='',searchGeneration=0,busy=false;\nfunction notify(s){const m=document.getElementById('message');m.textContent=s;m.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>m.style.display='none',6000)}\nfunction persist(){try{localStorage.setItem(key,JSON.stringify({templates:state.templates,draft:state.draft,records:[]}));storageOK=true;return true}catch(e){storageOK=false;notify('Browser storage is unavailable or full. Download a backup before closing this window.');return false}}\nfunction invalidateAll(){const d=state.draft;if(d.supervisorSignature||d.people.some(p=>p.signature)){d.supervisorSignature=null;d.people.forEach(p=>{p.signature=null;p.ack=false});document.querySelectorAll('.signature-image,.signature-time,.signature-status small').forEach(el=>el.remove());document.querySelectorAll('.person .check input').forEach(el=>el.checked=false);document.querySelectorAll('button[onclick^=\"openSignature\"]').forEach(el=>el.textContent=el.getAttribute('onclick').includes('supervisor')?'Supervisor sign':'Attendee sign');notify('Talk changed. Please collect fresh signatures before completing.')}}\nfunction field(k,v){if(state.draft[k]!==v)invalidateAll();state.draft[k]=v;persist()}\nfunction topic(i,k,v){if(state.draft.topics[i][k]!==v)invalidateAll();state.draft.topics[i][k]=v;persist()}\nfunction person(i,k,v){const p=state.draft.people[i];if(p[k]!==v)invalidateAll();p[k]=v;persist()}\nfunction action(i,k,v){if(state.draft.actions[i][k]!==v)invalidateAll();state.draft.actions[i][k]=v;persist()}\nfunction input(k,title,type='text'){return `<div><label for=\"${k}\">${title}</label><input id=\"${k}\" type=\"${type}\" value=\"${esc(state.draft[k])}\" oninput=\"field('${k}',this.value)\"></div>`}\nfunction view(p){if(!actor)return loginView();page=p;if(p==='admin'&&!actor.isAdmin)return notify('Administrator access required.');document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));document.getElementById('nav-'+p).classList.add('active');document.getElementById('main').innerHTML=p==='talk'?talkHTML():p==='admin'?adminHTML():recordsHTML()}\nfunction talkHTML(){const d=state.draft;return `<div class=\"row between\"><div><h2>${d.type==='daily'?'Daily pre-start':'Weekly toolbox talk'}</h2><span class=\"muted\">Prepare, discuss and record the agreed next steps.</span></div><span class=\"tag\">DRAFT</span></div><div class=\"card\"><div class=\"row\"><button onclick=\"newTalk('daily')\">+ New daily pre-start</button><button onclick=\"newTalk('weekly')\">+ New weekly talk</button></div><p class=\"muted\">New talks use your admin templates. Save this draft before starting another talk.</p><div class=\"grid\">${input('company','Company')}${input('site','Workshop / project *')}${input('date','Date *','date')}${input('time','Start time *','time')}${input('facilitator','Facilitator *')}${input('focus',d.type==='weekly'?'Weekly focus topic *':'Shift / team')}</div><label for=\"tasks\" style=\"margin-top:16px\">${d.type==='daily'?'Today’s tasks and changed conditions *':'Work and changes this week'}</label><textarea id=\"tasks\" oninput=\"field('tasks',this.value)\">${esc(d.tasks)}</textarea></div><div class=\"card\"><h3>Talking points & discussion</h3><p class=\"muted\">Edit the talking points for this session. Record the crew’s comments and check each section after it has been discussed.</p>${d.topics.map((t,i)=>`<section class=\"topic\"><h3>${String(i+1).padStart(2,'0')} · ${titles[i]}</h3><div class=\"grid\"><div><label for=\"point${i}\">Admin talking points</label><textarea id=\"point${i}\" oninput=\"topic(${i},'text',this.value)\">${esc(t.text)}</textarea></div><div><label for=\"note${i}\">Comments / discussion / agreed controls</label><textarea id=\"note${i}\" placeholder=\"Record the team’s comments…\" oninput=\"topic(${i},'notes',this.value)\">${esc(t.notes)}</textarea></div></div><label class=\"check\"><input type=\"checkbox\" ${t.reviewed?'checked':''} onchange=\"topic(${i},'reviewed',this.checked)\"> Discussed with the team</label></section>`).join('')}</div><div class=\"card\"><div class=\"row between\"><h3>Attendance & acknowledgement</h3><button onclick=\"invalidateAll();state.draft.people.push({name:'',ack:false,signature:null});persist();view('talk')\">+ Add attendee</button></div><p class=\"muted\">Once the discussion is finished, pass this device to each attendee to sign beside their name. By signing, they confirm attendance and an opportunity to ask questions.</p>${d.people.length?d.people.map((p,i)=>`<div class=\"person\"><div class=\"row\"><input aria-label=\"Attendee ${i+1} name\" placeholder=\"Full name\" value=\"${esc(p.name)}\" style=\"flex:1\" oninput=\"person(${i},'name',this.value)\"><button aria-label=\"Remove attendee ${i+1}\" onclick=\"invalidateAll();state.draft.people.splice(${i},1);persist();view('talk')\">Remove</button></div><label class=\"check\" style=\"margin-top:10px\"><input type=\"checkbox\" ${p.ack?'checked':''} disabled> Attendance and acknowledgement confirmed</label><div class=\"row signature-status\">${p.signature?`<img class=\"signature-image\" src=\"${esc(p.signature.image)}\" alt=\"Signature of ${esc(p.name)}\"><small>${esc(stamp(p.signature.at))}</small>`:\"\"}<button onclick=\"openSignature(${i})\">${p.signature?\"Sign again\":\"Attendee sign\"}</button></div></div>`).join(''):'<p class=\"empty\">Add the people attending this talk.</p>'}</div><div class=\"card\"><div class=\"row between\"><h3>Follow-up actions</h3><button onclick=\"invalidateAll();state.draft.actions.push({text:'',owner:'',due:'',closed:false});persist();view('talk')\">+ Add action</button></div><p class=\"muted\">Assign an owner and due date. Address any unsafe condition before the affected task starts.</p>${d.actions.map((a,i)=>`<div class=\"action\"><label for=\"act${i}\">Action ${i+1}</label><textarea id=\"act${i}\" oninput=\"action(${i},'text',this.value)\">${esc(a.text)}</textarea><div class=\"grid\"><div><label for=\"owner${i}\">Owner</label><input id=\"owner${i}\" value=\"${esc(a.owner)}\" oninput=\"action(${i},'owner',this.value)\"></div><div><label for=\"due${i}\">Due date</label><input id=\"due${i}\" type=\"date\" value=\"${esc(a.due)}\" oninput=\"action(${i},'due',this.value)\"></div></div><button onclick=\"invalidateAll();state.draft.actions.splice(${i},1);persist();view('talk')\">Remove action</button></div>`).join('')||'<p class=\"empty\">No actions added.</p>'}</div><div class=\"card\"><h3>Supervisor sign-off</h3><p>I confirm I conducted this talk and recorded the attendance, discussion and agreed actions.</p>${d.supervisorSignature?`<img class=\"signature-image\" src=\"${esc(d.supervisorSignature.image)}\" alt=\"Supervisor signature\"><p class=\"muted signature-time\">${esc(d.facilitator)} · ${esc(stamp(d.supervisorSignature.at))}</p>`:\"\"}<button onclick=\"openSignature('supervisor')\">${d.supervisorSignature?\"Sign again\":\"Supervisor sign\"}</button></div><div class=\"notice\">Export a completed copy as HTML or choose Save as PDF, then upload the file to your OneDrive folder. OneDrive upload is manual.</div><div class=\"actions\"><button onclick=\"saveDraft()\">Save draft</button><button class=\"primary\" onclick=\"completeTalk()\">Complete & save record</button><button onclick=\"pdf(state.draft)\">Save as PDF</button><button onclick=\"downloadReport(state.draft)\">Download record</button></div>`}\nfunction newTalk(type){if(busy)return notify('Wait for the save to finish.');if(!confirm('Start a new talk? Unsaved changes to the current talk will be replaced.'))return;state.draft=fresh(type);persist();view('talk')}\nasync function completeTalk(){const d=state.draft;if(!d.site.trim()||!d.facilitator.trim()||!d.date||!d.time||(d.type==='daily'&&!d.tasks.trim())||(d.type==='weekly'&&!d.focus.trim()))return notify('Fill in the required session details marked with *.');if(d.topics.some(t=>!t.reviewed||!t.text.trim()))return notify('Add talking points and confirm all six sections have been discussed.');if(!d.people.length||d.people.some(p=>!p.name.trim()||!p.ack||!p.signature))return notify('Add attendees and collect each attendee’s signature.');if(d.actions.some(a=>!a.text.trim()||!a.owner.trim()||!a.due))return notify('Each action needs a description, owner and due date.');if(!d.supervisorSignature)return notify('Collect the supervisor’s final sign-off.');await saveRecord(true);}\nfunction adminHTML(){return `<h2>Admin templates</h2><p class=\"muted\">Prepare recurring talking points for new talks. Changes do not alter existing talks or saved records.</p>${['daily','weekly'].map(type=>`<div class=\"card\"><h3>${type==='daily'?'Daily pre-start':'Weekly toolbox talk'}</h3>${titles.map((title,i)=>`<label for=\"${type}${i}\" style=\"margin-top:16px\">${title}</label><textarea id=\"${type}${i}\" oninput=\"state.templates.${type}[${i}]=this.value;persist()\">${esc(state.templates[type][i])}</textarea>`).join('')}</div>`).join('')}<div class=\"notice\"><button class=\"primary\" onclick=\"saveTemplates()\">Save shared templates</button> <button onclick=\"reloadTemplates()\">Reload shared templates</button><p>Template edits apply to new talks after you save. Adapt the prompts to your workplace procedures and risk assessments.</p></div>`}\nfunction recordsHTML(){return `<div class=\"row between\"><div><h2>Saved records</h2><p class=\"muted\">${totalRecords} matching shared records · ${openActionTotal} open actions</p></div><button onclick=\"refreshRecords()\">Refresh records</button></div><div class=\"card\"><h3>Outstanding actions</h3><p class=\"muted\">Showing ${openActions.length} actions on this page.</p>${openActions.length?openActions.map(a=>`<div class=\"person\"><strong>${esc(a.text)}</strong><p class=\"muted\">${esc(a.site)} · ${esc(a.owner)} · Due ${esc(a.due)}</p><button onclick=\"closeAction('${esc(a.record)}',${a.index},${a.revision})\">Mark resolved</button></div>`).join(''):'<p class=\"empty\">No outstanding actions on this page.</p>'}${pageControls(nextActionPage)}</div><div class=\"card\"><label for=\"search\">Search records</label><input id=\"search\" value=\"${esc(searchTerm)}\" placeholder=\"Workshop, facilitator, date or topic…\" oninput=\"filterRecords(this.value)\"><div id=\"records-list\">${recordRows(state.records)}</div><div id=\"record-pagination\">${pageControls(nextRecordPage)}</div></div><div class=\"notice\">Completed talks are preserved in PanelStock. Action resolution is tracked separately. Download the signed copy and upload it to OneDrive.</div>`}\nfunction pageControls(next){return `<div class=\"row\" style=\"margin-top:15px\">${recordPage>0?'<button onclick=\"loadPage('+Math.max(0,recordPage-25)+')\">Previous page</button>':''}${next!==null?'<button onclick=\"loadPage('+next+')\">Next page</button>':''}</div>`}\nfunction recordRows(rows){return rows.length?[...rows].reverse().map(r=>`<div class=\"person\"><div class=\"row between\"><strong>${r.type==='daily'?'Daily pre-start':'Weekly toolbox talk'} · ${esc(r.date)}</strong><span class=\"tag\">${esc(r.status)}</span></div><p class=\"muted\">${esc(r.site)} · ${esc(r.facilitator)} · ${r.people.length} attendees${r.focus?' · '+esc(r.focus):''}</p><div class=\"row\">${r.status==='Draft'?`<button onclick=\"openDraft('${esc(r.id)}')\">Edit draft</button>`:''}<button onclick=\"exportRecord('${esc(r.id)}','pdf')\">Save as PDF</button><button onclick=\"exportRecord('${esc(r.id)}','html')\">Download record</button></div></div>`).join(''):'<p class=\"empty\">No matching records.</p>'}\nfunction filterRecords(q){searchTerm=q;clearTimeout(filterRecords.timer);filterRecords.timer=setTimeout(()=>loadPage(0,true),300)}\nasync function openDraft(id){if(!confirm('Open this shared draft? Current unsaved changes will be replaced.'))return;try{const data=await api('/toolbox/records/'+id);state.draft=data.record;persist();view('talk')}catch(e){notify(e.message)}}\nasync function closeAction(id,index,revision){try{await api('/toolbox/records/'+id+'/resolve',{mutationId:crypto.randomUUID(),expectedRevision:revision,actionIndex:index});await loadPage(recordPage);notify('Action resolution saved in PanelStock.')}catch(e){notify(e.message)}}\nfunction stamp(s){return s?new Date(s).toLocaleString('en-AU',{timeZone:'Australia/Brisbane'})+' AEST':'—'}\nfunction report(d){return `<article class=\"report\"><small>FABRICATION TOOLBOX · ${esc(d.status.toUpperCase())}</small><h1>${d.type==='daily'?'Daily pre-start':'Weekly toolbox talk'}</h1><p><strong>Company:</strong> ${esc(d.company)}<br><strong>Workshop / project:</strong> ${esc(d.site)}<br><strong>Date / time:</strong> ${esc(d.date)} ${esc(d.time)}<br><strong>Facilitator:</strong> ${esc(d.facilitator)}<br><strong>Focus / team:</strong> ${esc(d.focus)}</p><h2>Work and changed conditions</h2><p>${esc(d.tasks)||'None recorded.'}</p>${d.topics.map((t,i)=>`<section><h2>${i+1}. ${titles[i]}</h2><strong>Talking points</strong><p>${esc(t.text)}</p><strong>Comments / discussion / agreed controls</strong><p>${esc(t.notes)||'None recorded.'}</p><p>Discussed: ${t.reviewed?'Yes':'No'}</p></section>`).join('')}<h2>Attendance & acknowledgement</h2><p>Each attendee signed on the supervisor’s device to acknowledge attendance and an opportunity to ask questions.</p><table><thead><tr><th>Name</th><th>Acknowledgement confirmed</th><th>Signature / time</th></tr></thead><tbody>${d.people.map(p=>`<tr><td>${esc(p.name)}</td><td>${p.ack?'Yes':'No'}</td><td>${p.signature?`<img src=\"${esc(p.signature.image)}\" alt=\"Signature of ${esc(p.name)}\" style=\"width:180px;height:60px;object-fit:contain\"><br>${esc(stamp(p.signature.at))}`:'Not signed'}</td></tr>`).join('')||'<tr><td colspan=\"3\">No attendees recorded.</td></tr>'}</tbody></table><h2>Follow-up actions</h2>${d.actions.map((a,i)=>`<section><p><strong>${i+1}. ${esc(a.text)}</strong><br>Owner: ${esc(a.owner)} · Due: ${esc(a.due)}<br>Status: ${a.closed?'Resolved '+stamp(a.resolvedAt):'Open'}</p></section>`).join('')||'<p>No actions recorded.</p>'}<h2>Supervisor sign-off</h2><p>I confirm I conducted this talk and recorded the attendance, discussion and agreed actions.</p><p>${esc(d.facilitator)}</p>${d.supervisorSignature?`<img src=\"${esc(d.supervisorSignature.image)}\" alt=\"Supervisor signature\" style=\"width:200px;height:70px;object-fit:contain\"><p>${esc(stamp(d.supervisorSignature.at))}</p>`:\"<p>Not signed</p>\"}<hr><p><small>Record ID: ${esc(d.id)}<br>Completed: ${stamp(d.completedAt)}<br>Exported: ${stamp(new Date().toISOString())}<br>Use workplace procedures and risk assessments for task-specific requirements.</small></p></article>`}\nasync function pdf(d){document.getElementById('printout').innerHTML=report(d);await Promise.all(Array.from(document.querySelectorAll('#printout img'),img=>img.decode()));const old=document.title;document.title=filename(d);window.print();document.title=old;}\nfunction filename(d){return [d.date,d.site||'workshop',d.type==='daily'?'Daily-Prestart':'Weekly-Toolbox',d.status,d.id.slice(0,8)].join('_').replace(/[^a-zA-Z0-9_.-]/g,'-')}\nfunction download(name,data,type){const blob=new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}\nfunction downloadReport(d){download(filename(d)+'.html','<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>'+esc(filename(d))+'</title><style>body{max-width:850px;margin:35px auto;padding:0 24px;font:14px Arial;line-height:1.5;color:#172a32}h2{font-size:18px;margin-top:25px}p{white-space:pre-wrap;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse}td,th{border:1px solid #bbc8cd;padding:8px;text-align:left}section{break-inside:avoid}@page{size:A4;margin:16mm}</style>'+report(d)+'</html>','text/html');notify('Record downloaded. Upload the file to OneDrive.');}\nasync function backup(){if(busy)return;busy=true;try{const records=[],snapshot=await api('/toolbox/export-index',{});for(const id of snapshot.ids){records.push((await api('/toolbox/records/'+id)).record);notify('Exporting '+records.length+' of '+snapshot.ids.length+' shared records…');}download('PanelStock-Toolbox-Records_'+today()+'.json',JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),templates:snapshot.templates,records},null,2),'application/json');notify('Shared records exported. Store this backup securely.')}catch(e){notify(e.message)}finally{busy=false}}\nfunction downloadDraft(){download('PanelStock-Toolbox-Draft_'+today()+'.json',JSON.stringify(state.draft,null,2),'application/json')}\nasync function restoreFile(input){try{const file=input.files[0];if(!file)return;if(file.size>5000000)throw Error('Choose a draft under 5 MB');const d=JSON.parse(await file.text());if(!validRecord(d)||d.status!=='Draft')throw Error('Choose a valid toolbox draft backup');if(!confirm('Replace the current device draft? Shared records will be unchanged until you save.'))return;state.draft=d;persist();view('talk');notify('Draft recovered on this device.')}catch(e){notify(e.message)}finally{input.value=''}}\nfunction loginView(){document.querySelector('nav').inert=true;document.getElementById('main').innerHTML=`<div class=\"card\"><h2>Supervisor sign-in</h2><p>Use your PanelStock username and PIN. Workers sign on this device after the talk.</p><form onsubmit=\"event.preventDefault();login()\"><label for=\"username\">Username</label><input id=\"username\" autocomplete=\"username\" required><label for=\"pin\" style=\"margin-top:15px\">PIN</label><input id=\"pin\" type=\"password\" inputmode=\"numeric\" autocomplete=\"current-password\" required><button class=\"primary\" style=\"margin-top:18px\">Sign in</button></form></div>`;document.getElementById('logout').hidden=true;document.getElementById('signed-in').textContent='';}\nasync function api(path,body){const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:body===undefined?undefined:JSON.stringify(body)});let data;try{data=await r.json()}catch{throw Error('PanelStock returned an unexpected response. No save was confirmed.')};if(!r.ok){if(r.status===401){actor=null;token='';sessionStorage.removeItem('panelstock-toolbox-session');loginView()}throw Error(data.error||'No successful save was confirmed.')}return data}\nasync function login(){const username=document.getElementById('username').value,pin=document.getElementById('pin').value;try{const session=await api('/login',{username,pin,app:'app'});if(session.mustChangePin)throw Error('Update your PIN in PanelStock before opening the toolbox.');token=session.token;sessionStorage.setItem('panelstock-toolbox-session',token);await startSession()}catch(e){notify(e.message)}}\nasync function startSession(){try{const session=await api('/session');if(!session.isAdmin&&!session.taskAccess?.['factory.toolbox']){token='';sessionStorage.removeItem('panelstock-toolbox-session');throw Error('Ask your PanelStock administrator to enable Run toolbox talks for your account.')}actor=session;document.querySelector('nav').inert=false;key='panelstock-toolbox-v1:'+actor.username;state={templates:{daily:[...daily],weekly:[...weekly]},records:[],draft:null};const local=localStorage.getItem(key);if(local){try{const data=JSON.parse(local),cached={templates:data.templates,draft:data.draft,records:[]};if(validState(cached))state=cached;else notify('The saved device draft is invalid. Recover a draft backup if needed.')}catch{notify('The saved device draft could not be loaded. Recover a draft backup if needed.')}}const hadDraft=!!state.draft;await reloadTemplates(false);if(!hadDraft)state.draft=fresh();await loadPage(0,false);document.getElementById('nav-admin').hidden=!actor.isAdmin;document.getElementById('logout').hidden=false;document.getElementById('signed-in').textContent=actor.username;view('talk')}catch(e){actor=null;loginView();notify(e.message)}}\nasync function logout(){if(busy)return notify('Wait for the current operation to finish.');if(!persist()&&!confirm('The device draft could not be saved. Log out anyway?'))return;try{await api('/logout',{})}catch(e){notify(e.message)}token='';actor=null;sessionStorage.removeItem('panelstock-toolbox-session');loginView()}\nasync function reloadTemplates(render=true){try{const data=await api('/toolbox/templates');state.templates=data.templates;templateRevision=data.revision;if(render)view('admin')}catch(e){notify(e.message);throw e}}\nasync function saveTemplates(){if(!actor?.isAdmin)return;if(busy)return;busy=true;try{const data=await api('/toolbox/templates',{templates:state.templates,expectedRevision:templateRevision});templateRevision=data.revision;state.templates=data.templates;persist();notify('Shared templates saved.')}catch(e){notify(e.message)}finally{busy=false}}\nasync function loadPage(offset=0,render=true){const generation=++searchGeneration;try{const data=await api('/toolbox/list',{offset,search:searchTerm});if(generation!==searchGeneration)return;state.records=data.records;recordPage=offset;totalRecords=data.total;openActions=data.openActions;openActionTotal=data.openActionTotal;nextRecordPage=data.nextOffset;nextActionPage=data.actionNextOffset;if(render){const focused=document.activeElement?.id==='search',caret=focused?document.activeElement.selectionStart:null;view('records');if(focused){const search=document.getElementById('search');search.focus();search.setSelectionRange(caret,caret)}}}catch(e){notify(e.message)}}\nasync function refreshRecords(){if(!actor)return loginView();await loadPage(0)}\nasync function exportRecord(id,format){try{const r=(await api('/toolbox/records/'+id)).record;if(format==='pdf')pdf(r);else downloadReport(r)}catch(e){notify(e.message)}}\nasync function saveDraft(){await saveRecord(false)}\nasync function saveRecord(complete){if(busy)return;busy=true;document.querySelector('.shell').inert=true;const d=state.draft;try{const record=structuredClone(d);delete record.pendingSave;record.status=complete?'Completed':'Draft';const packet={record,expectedRevision:d.revision||0,mutationId:crypto.randomUUID()};const fingerprint=JSON.stringify({record,expectedRevision:packet.expectedRevision});if(d.pendingSave?.fingerprint===fingerprint)packet.mutationId=d.pendingSave.mutationId;d.pendingSave={fingerprint,mutationId:packet.mutationId};persist();const data=await api('/toolbox/records/'+d.id,packet);if(complete)state.draft=fresh(d.type);else{const revision=data.record.revision,changed=toolboxContent(d)!==toolboxContent(record);state.draft=changed?{...d,revision,pendingSave:null}:{...data.record,pendingSave:null}}persist();if(complete){await loadPage(0);view('records')}notify(complete?'Signed record saved in PanelStock. Export a copy for OneDrive.':'Draft saved in PanelStock.')}catch(e){notify(e.message+' Your device draft has been retained.')}finally{busy=false;document.querySelector('.shell').inert=false}}\nfunction toolboxContent(r){\n const trim=v=>String(v??'').trim();\n return JSON.stringify({id:r.id,type:r.type,date:trim(r.date),time:trim(r.time),company:trim(r.company),site:trim(r.site),facilitator:trim(r.facilitator),tasks:trim(r.tasks),focus:trim(r.focus),topics:r.topics.map(t=>({text:trim(t.text),notes:trim(t.notes),reviewed:t.reviewed===true})),people:r.people.map(p=>({name:trim(p.name)})),actions:r.actions.map(a=>({text:trim(a.text),owner:trim(a.owner),due:trim(a.due)}))});\n}\nasync function contentHash(r){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(toolboxContent(r)));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('')}\nlet signing=null,ink=false,activePointer=null;\nfunction openSignature(target){const d=state.draft;if(!d.site.trim()||!d.facilitator.trim()||(d.type==='daily'?!d.tasks.trim():!d.focus.trim())||d.topics.some(t=>!t.reviewed||!t.text.trim())||!d.people.length||d.people.some(p=>!p.name.trim())||d.actions.some(a=>!a.text.trim()||!a.owner.trim()||!a.due))return notify('Finish the talk details, discussion, attendee names and actions before signing.');const name=target==='supervisor'?d.facilitator:d.people[target]?.name;if(!name?.trim())return notify('Enter the signer’s name first.');if(target==='supervisor'&&(!d.people.length||d.people.some(p=>!p.signature)))return notify('Collect attendee signatures before the supervisor sign-off.');signing=target;document.getElementById('sign-title').textContent=name;document.getElementById('sign-statement').textContent=target==='supervisor'?'I confirm I conducted this talk and recorded attendance, discussion and agreed actions.':'I attended this talk and had an opportunity to ask questions and raise concerns.';document.getElementById('sign-dialog').showModal();const c=document.getElementById('signature-pad');c.width=1000;c.height=350;clearPad();}\nfunction clearPad(){const c=document.getElementById('signature-pad'),ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#172c35';ctx.fillStyle='#172c35';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';ink=false;activePointer=null;}\nasync function saveSignature(){if(!ink)return notify('Draw a signature before saving.');const signature={image:document.getElementById('signature-pad').toDataURL('image/png'),at:new Date().toISOString(),contentHash:await contentHash(state.draft)};if(signing==='supervisor')state.draft.supervisorSignature=signature;else{state.draft.people[signing].signature=signature;state.draft.people[signing].ack=true;state.draft.supervisorSignature=null;}persist();document.getElementById('sign-dialog').close();view('talk');}\nconst pad=document.getElementById('signature-pad');\nfunction point(e){const r=pad.getBoundingClientRect();return [(e.clientX-r.left)*pad.width/r.width,(e.clientY-r.top)*pad.height/r.height]}\npad.addEventListener('pointerdown',e=>{if(activePointer!==null)return;e.preventDefault();activePointer=e.pointerId;pad.setPointerCapture(e.pointerId);const ctx=pad.getContext('2d'),[x,y]=point(e);ctx.beginPath();ctx.arc(x,y,2,0,2*Math.PI);ctx.fill();ctx.beginPath();ctx.moveTo(x,y);ink=true;});\npad.addEventListener('pointermove',e=>{if(e.pointerId!==activePointer)return;e.preventDefault();const ctx=pad.getContext('2d');ctx.lineTo(...point(e));ctx.stroke();});\nfor(const event of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(event,e=>{if(e.pointerId===activePointer){activePointer=null;persist();}});\n\nif(token)startSession();else loginView();\n</script></html>\n";}
